import {validate} from './engine.js';
export function importProject(text){if(text.trim().startsWith('{')){const obj=JSON.parse(text);return validate(obj.model||obj,false)}const doc=new DOMParser().parseFromString(text,'text/xml');if(doc.querySelector('parsererror'))throw Error('invalidModel');const type=doc.querySelector('structure > type')?.textContent;if(!['fa','pda','turing'].includes(type)||doc.querySelector('tapes')&&doc.querySelector('tapes').textContent!=='1')throw Error('invalidModel');if([...doc.querySelectorAll('[tape]')].some(e=>e.getAttribute('tape')!=='1'))throw Error('invalidModel');const states=[...doc.querySelectorAll('automaton > state')].map(s=>({id:s.getAttribute('id'),name:s.getAttribute('name')||'q',x:Number(s.querySelector('x')?.textContent||200),y:Number(s.querySelector('y')?.textContent||200),initial:!!s.querySelector('initial'),final:!!s.querySelector('final')}));const value=(s,key)=>s.querySelector(key)?.textContent||'';const edges=[...doc.querySelectorAll('automaton > transition')].map(e=>({from:value(e,'from'),to:value(e,'to'),read:value(e,'read')||(type==='turing'?'□':''),...(type==='pda'?{pop:value(e,'pop'),push:value(e,'push')}:{ }),...(type==='turing'?{write:value(e,'write')||'□',move:value(e,'move')}: {})}));return validate({type:type==='turing'?'tm':type,states,edges},false)}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
export function jflap(m){validate(m,false);const ids=new Map(m.states.map((s,i)=>[s.id,i]));const tag=(k,v)=>`<${k}>${esc(v)}</${k}>`;return '<?xml version="1.0" encoding="UTF-8"?><structure>'+tag('type',m.type==='tm'?'turing':m.type)+'<automaton>'+m.states.map(s=>`<state id="${ids.get(s.id)}" name="${esc(s.name)}">${tag('x',s.x)+tag('y',s.y)}${s.initial?'<initial/>':''}${s.final?'<final/>':''}</state>`).join('')+m.edges.map(e=>'<transition>'+tag('from',ids.get(e.from))+tag('to',ids.get(e.to))+tag('read',e.read==='□'?'':e.read)+(m.type==='pda'?tag('pop',e.pop)+tag('push',e.push):'')+(m.type==='tm'?tag('write',e.write==='□'?'':e.write)+tag('move',e.move):'')+'</transition>').join('')+'</automaton></structure>'}
export function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
